package com.smartretail.billing.security;
import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException; import java.util.List;
public class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; public JwtFilter(JwtService jwt){this.jwt=jwt;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException {String h=req.getHeader("Authorization"); if(h!=null&&h.startsWith("Bearer ")){String t=h.substring(7).trim();if(!jwt.valid(t)||jwt.businessId(t)==null||jwt.username(t)==null){res.sendError(401,"Invalid or expired token.");return;} SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(jwt.username(t),null,List.of()));req.setAttribute("businessId",jwt.businessId(t));}chain.doFilter(req,res);} }
